      if (hit < .5 && kc > 0.) ext = L - 24.0*kc;          // miss: reel back in
      float s = ext - i*SP;                                             // this link's distance from the hand
      float life = hit > .5 ? tR + 1.92 : tR + L/24.0;
      // II · Pull (aP = recast time, written once by the CPU on the live chain): interrupt pulse runs tip → hand,
      // then the chain contracts violently (ease-in) and reels into the hand, bringing the target to melee range
      float kp = uTime - aP, pulled = step(.5, aP)*step(0., kp);
      float pc = clamp((kp - 0.12)/0.22, 0., 1.), pe = pc*pc*pc*pulled;
      s -= (L - 0.75)*pe;
